cat > /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/bench-tmp-jse7sm26/opencode/UITests/LinkTest.swift <<'EOF'
import XCTest

final class LinkTest: XCTestCase {
    func testAcceptBlueskyLink() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        if openButton.waitForExistence(timeout: 10) {
            openButton.tap()
        }
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        XCTAssertTrue(bluesky.wait(for: .runningForeground, timeout: 15))
    }
}
EOF

